import * as React from "react";

export type FilmReelIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function FilmReelIcon({ size = 20, ...props }: FilmReelIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8" /><circle cx="12" cy="12" r="1.5" /><circle cx="12" cy="7" r="1.5" /><circle cx="8" cy="15" r="1.5" />
    </svg>
  );
}
